package br.com.admeclesial.interfaces.rest.financeiro; import br.com.admeclesial.application.financeiro.*; import br.com.admeclesial.domain.financeiro.Fornecedor; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/v1/fornecedores") public class FornecedorRestController { final FornecedorApplicationService s; public FornecedorRestController(FornecedorApplicationService s){this.s=s;} @PostMapping public Fornecedor criar(@Valid @RequestBody FornecedorRequest r){return s.criar(r);} @GetMapping public List<Fornecedor> listar(){return s.listar();} }